set-variable.value:
@{
      var config = JObject.Parse(System.Text.Encoding.UTF8.GetString(Convert.FromBase64String("__AUTHORIZATION_BASE64__")));
      var deny = new JObject(new JProperty("allowed", false));
      var keyHeader = (string)context.Variables["gatewayKeyHeader"];
      if ((string)config["mode"] != "subscriptionKey" || context.Subscription == null
          || String.IsNullOrWhiteSpace(context.Subscription.Id) || !context.Request.Headers.ContainsKey(keyHeader)
          || context.Request.Headers[keyHeader].Length != 1
          || String.IsNullOrWhiteSpace(context.Request.Headers.GetValueOrDefault(keyHeader, ""))) { return deny.ToString(); }
      var decision = new JObject(new JProperty("allowed", true),
        new JProperty("callerId", "subscription:" + context.Subscription.Id), new JProperty("method", "subscriptionKey"));
      if (context.Variables.ContainsKey("gatewayProfileSelection")) {
        var profileId = (string)JObject.Parse((string)context.Variables["gatewayProfileSelection"])["profileId"];
        if (!String.IsNullOrEmpty(profileId)) { decision["profileId"] = profileId; }
      }
      return decision.ToString(Newtonsoft.Json.Formatting.None);
    }

@{
      try {
        var message = context.Request.Body.As<JObject>(preserveContent: true);
        if ((string)message?["method"] != "tools/call" || message["id"]?.Type != JTokenType.Integer) { return ""; }
        var name = (string)message["params"]?["name"];
        var config = JObject.Parse(System.Text.Encoding.UTF8.GetString(Convert.FromBase64String("__AUTHORIZATION_BASE64__")));
        var constraint = String.IsNullOrEmpty(name) ? null : config["operationConstraints"]?[name] as JObject;
        if ((string)constraint?["kind"] != "pii") { return ""; }
        var arguments = message["params"]?["arguments"] as JObject;
        var valid = arguments != null && arguments.Properties().Count() == 2
          && arguments.Properties().All(p => p.Name == "text" || p.Name == "language")
          && arguments["text"]?.Type == JTokenType.String && !String.IsNullOrWhiteSpace((string)arguments["text"])
          && arguments["language"]?.Type == JTokenType.String
          && ((JArray)constraint["allowedLanguages"]).Any(v => (string)v == (string)arguments["language"])
          && System.Text.Encoding.UTF8.GetByteCount(arguments.ToString(Newtonsoft.Json.Formatting.None)) <= (int)constraint["maxRequestBytes"];
        if (valid) { return ""; }
        return new JObject(new JProperty("jsonrpc", "2.0"), new JProperty("id", message["id"]),
          new JProperty("error", new JObject(new JProperty("code", -32602), new JProperty("message", "Invalid tool arguments")))).ToString(Newtonsoft.Json.Formatting.None);
      } catch { return ""; }
    }
